UPDATE peliculas SET synopsis='Los Oniros son los hijos del sueño. Fantaso, hermano de morfeo, se encargaba de los sueños en los que aparecían elementos inanimados de la naturaleza, tales como rocas, agua o árboles. Es el provocador de las fantasías que nublan la razón creando la confusión entre lo real y lo ficticio. En la pandemia lo quieto e inerte deja irse en la fantasía melancólica de lo vivo y libre.', duration='2m 22s', author='Creado por: Andrezpanda; Ilustración por: Londoanor' WHERE slug='fantaso4';
