UPDATE peliculas SET synopsis='Un robot hábil en todas las técnicas y uso de maquinaría para la guerra, se encuentra desorientado al darse cuenta que la guerra terminó y no encuentra un lugar para ejercerse. Sin lugar a donde ir, vaga sin rumbo hasta que finalmente se encuentra con un pueblo y la promesa de un nuevo comienzo. Tras múltiples fracasos por encontrar un nuevo propósito, el robot decide desarmarse y entregarse a los afectados por la guerra. Encontrado así una forma de ser útil en este nuevo mundo.', duration='7m 6s', author='Creado por: Juan Ureña; Ilustración por: Sirenas Migrantes' WHERE slug='la-fabrica-de-desahuciados';
